import fs from 'node:fs';
import path from 'node:path';

// A deliberately tiny "compiler": it prepends header lines and copies every source line, so each
// original line lands on a known generated line. It writes a flat Source Map v3 inline or beside
// the output. It exists so translation tests never depend on a real language toolchain.

const BASE64_DIGITS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

export function encodeVlq(value) {
  let remaining = value < 0 ? (-value << 1) | 1 : value << 1;
  let encoded = '';
  do {
    let digit = remaining & 31;
    remaining >>>= 5;
    if (remaining) digit |= 32;
    encoded += BASE64_DIGITS[digit];
  } while (remaining);
  return encoded;
}

const HEADER = ['// generated by the source-map fixture compiler', ''];

export function compile({ generatedPath, sources, placement = 'sibling', unmapped = [], extraSegment, mapOverrides = {} }) {
  const lines = [...HEADER];
  const mappingLines = HEADER.map(() => '');
  const generatedLineOf = {};
  const previous = { source: 0, line: 0 };
  sources.forEach((source, sourceIndex) => {
    const text = fs.readFileSync(source, 'utf8');
    text.replace(/\n$/, '').split('\n').forEach((originalText, originalIndex) => {
      lines.push(originalText);
      generatedLineOf[`${sourceIndex}:${originalIndex + 1}`] = lines.length;
      if (unmapped.some((entry) => entry.source === sourceIndex && entry.line === originalIndex + 1)) return mappingLines.push('');
      mappingLines.push([0, sourceIndex - previous.source, originalIndex - previous.line, 0].map(encodeVlq).join(''));
      Object.assign(previous, { source: sourceIndex, line: originalIndex });
    });
  });
  if (extraSegment) mappingLines[extraSegment.generatedLine - 1] = extraSegment.text;
  const mapPath = generatedPath + '.map';
  const mapDirectory = placement === 'inline' ? path.dirname(generatedPath) : path.dirname(mapPath);
  const map = {
    version: 3,
    file: path.basename(generatedPath),
    sources: sources.map((source) => path.relative(mapDirectory, source).replaceAll('\\', '/')),
    sourcesContent: sources.map((source) => fs.readFileSync(source, 'utf8')),
    names: [],
    mappings: mappingLines.join(';'),
    ...mapOverrides,
  };
  const mapJson = JSON.stringify(map);
  let generated = lines.join('\n') + '\n';
  if (placement === 'inline') generated += `//# sourceMappingURL=data:application/json;base64,${Buffer.from(mapJson).toString('base64')}\n`;
  if (placement === 'declared') generated += `//# sourceMappingURL=${path.basename(mapPath)}\n`;
  fs.mkdirSync(path.dirname(generatedPath), { recursive: true });
  fs.writeFileSync(generatedPath, generated);
  if (placement !== 'inline') fs.writeFileSync(mapPath, mapJson);
  return { generatedPath, mapPath: placement === 'inline' ? null : mapPath, generatedLineOf, map };
}

// LCOV the way a coverage tool would record it against the generated file.
export function generatedLcov(lcovName, compiled, hits, functions = []) {
  const records = Object.entries(hits).map(([key, count]) => `DA:${compiled.generatedLineOf[key]},${count}`);
  const definitions = functions.flatMap(({ key, name, count }) => [`FN:${compiled.generatedLineOf[key]},${name}`, `FNDA:${count},${name}`]);
  return [`SF:${lcovName}`, ...definitions, ...records, 'end_of_record', ''].join('\n');
}
